<section class="page-wrap admin-wrap"><div class="admin-head"><div><span class="section-kicker">Communauté</span><h1>Utilisateurs</h1><p>Gérez les accès à l'espace Rachel Naturo.</p></div></div><div class="admin-columns content-admin"><section class="panel"><div class="panel-head"><div><span class="section-kicker">Inviter</span><h2>Créer un accès</h2></div></div><form class="admin-form" method="post" action="/admin/utilisateurs"><label>Nom complet<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Mot de passe<input type="password" name="password" required></label><label>Rôle<select name="role"><option value="user">Membre</option><option value="admin">Administrateur</option></select></label><button class="button button-dark" type="submit">Ajouter le membre <span>→</span></button></form></section><section class="panel"><div class="panel-head"><div><span class="section-kicker">Membres</span><h2><?= count($users) ?> accès</h2></div></div><?php foreach ($users as $user): ?><div class="user-row"><span class="avatar small-avatar"><?= strtoupper(substr($user['name'], 0, 1)) ?></span><div><b><?= htmlspecialchars($user['name']) ?></b><small><?= htmlspecialchars($user['email']) ?></small></div><form method="post" action="/admin/utilisateurs/modifier"><input type="hidden" name="id" value="<?= $user['id'] ?>"><select name="role" title="Modifier le rôle" onchange="this.form.submit()"><option value="user" <?= $user['role'] === 'user' ? 'selected' : '' ?>>Membre</option><option value="admin" <?= $user['role'] === 'admin' ? 'selected' : '' ?>>Admin</option></select></form><?php if ((int) $user['id'] !== (int) $_SESSION['user']['id']): ?><form method="post" action="/admin/utilisateurs/supprimer"><input type="hidden" name="id" value="<?= $user['id'] ?>"><button class="delete-button" title="Supprimer l'utilisateur">×</button></form><?php endif; ?></div><?php endforeach; ?></section></div></section>
